INT15_20        proc near               ; CODE XREF: INT15_22+4↓p
                mov     al, dl          ; AH=20h (select the tone+volume service)
                                        ; AL (low 2 bits): channel (0,1,2 — possibly 3=noise)
                                        ; DX: 10-bit tone period N
                                        ; low 4 bits in DL[3:0] (used in the latch byte)
                                        ; high 6 bits in (DX >> 4) & 0x3F (second data byte)
                                        ; CH: volume attenuation (0..15) — 0 = max volume, 15 = mute
                and     al, 0Fh
                or      al, ah
                or      al, 80h
                out     14h, al
                mov     cl, 4
                shr     dx, cl
                mov     al, dl
                out     14h, al
                call    INT15_21
                retn
INT15_20        endp


